class JobStore:
    def __init__(self):
        self.rows = {}

    def save(self, job_id, payload):
        self.rows[job_id] = payload

    def get(self, job_id):
        return self.rows[job_id]

def publish(store, job_id, payload):
    store.save(job_id, payload)
    payload['status'] = 'sent'
